const templates=Object.keys(DYNAMIC_TRANSLATIONS.en)
 .sort((a,b)=>b.length-a.length)
 .map(source=>{
  const parts=source.split(/(\{[0-9]+\})/g);
  const markers=[];
  const expr=parts.map(part=>{
   if(/^\{[0-9]+\}$/.test(part)){
    markers.push(Number(part.slice(1,-1)));
    return '(.{1,220}?)';
   }
   return part.replace(/[.*+?^$|{}()[\]\\]/g,'\\$&');
  }).join('');
  return {source,markers,pattern:new RegExp('^'+expr+'$','u')};
 });
export function translateOfficerDynamicText(source,lang='de'){
 if(lang==='de'||!DYNAMIC_TRANSLATIONS[lang]||typeof source!=='string'||source.length>1100)return source;
 for(const template of templates){
  const match=template.pattern.exec(source);
  if(!match)continue;
  const translated=DYNAMIC_TRANSLATIONS[lang][template.source];
  if(!translated||translated===template.source)continue;
  const values={};
  template.markers.forEach((index,i)=>{values[index]=match[i+1]});
  if(lang==='en' && template.source==='{0} Spieler')return values[0]+(Number(values[0])===1?' player':' Players');
  return translated.replace(/\{([0-9]+)\}/g,(_,i)=>values[Number(i)]??'');
 }
 return source;
}
export const OFFICER_DYNAMIC_TEMPLATES=Object.freeze(templates.map(t=>t.source));
